//! 🧪️ Neutral matrices preserve source origins, glyph bases and image corner orientation.
use super::*;
fn map(a:[f64;6],p:[f64;2])->[f64;2]{[a[0]*p[0]+a[2]*p[1]+a[4],a[1]*p[0]+a[3]*p[1]+a[5]]}
#[test]fn portable_pdf_matrices_preserve_unrounded_local_geometry(){let corpus:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let a=std::array::from_fn(|i|row["affine"][i].as_f64().unwrap());let origin=std::array::from_fn(|i|row["origin"][i].as_f64().unwrap());let height=row["height"].as_f64().unwrap();let world=map(a,origin);let projected=map(path_matrix(a,height),origin);assert!((world[0]-projected[0]).abs()<1e-6);assert!((height-world[1]-projected[1]).abs()<1e-6);let text=text_matrix(a,origin,height,row["italic"].as_bool().unwrap());assert_eq!(text[4],projected[0]);assert!((text[5]-projected[1]).abs()<1e-6);let image=image_matrix(a,[2.0,3.0,5.0,7.0],height);let bottom=map(path_matrix(a,height),[2.0,10.0]);assert!((image[4]-bottom[0]).abs()<1e-3&&(image[5]-bottom[1]).abs()<1e-3);}}
